INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000028b',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss urban planning at B2","Use Stadtplanung vocabulary","Talk about sustainable city design and planning challenges"],"explanation":{"intro":"Urban planning vocabulary covers city design, zoning, public space, and sustainable urban development at B2.","culturalNote":"Stadtplanung: Germany has a detailed planning law (Baugesetzbuch — Federal Building Code). Key instruments: Bebauungsplan (local development plan — binding), Flächennutzungsplan (land use plan — preparatory), Städtebaulicher Rahmenplan. Key challenges: Verdichtung (densification — adding housing without sprawl), Dachaufstockung (roof-top additions), Gentrifizierung (gentrification), Stadtumbau (urban conversion — East Germany shrinking cities). Smart City: Sensortechnik, Datengestützte Stadtplanung. Key principles: Mischnutzung (mixed use — living + working + retail), Verkehrsberuhigung (traffic calming), Stadt der kurzen Wege (city of short distances). Berlin''s Tempelhofer Feld debate."},"examples":[{"german":"Nachhaltige Stadtplanung muss widersprüchliche Anforderungen in Einklang bringen: Verdichtung als Beitrag zum Flächenschutz kollidiert mit dem Erhalt grüner Freiflächen und dem Wunsch nach Lebensqualität im öffentlichen Raum.","english":"Sustainable urban planning must bring contradictory requirements into alignment: densification as a contribution to land protection collides with the preservation of green open spaces and the desire for quality of life in public space."},{"german":"Das Konzept der ''Stadt der kurzen Wege'' zielt darauf ab, alltägliche Bedarfe innerhalb eines fußläufig erreichbaren Radius zu decken — eine Strategie, die Mobilität reduziert und Gemeinschaftssinn stärkt.","english":"The concept of the ''city of short distances'' aims to cover everyday needs within a walkable radius — a strategy that reduces mobility and strengthens community spirit."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss urban planning, densification, and sustainable city concepts at B2."}}',
'{"items":[{"word":"in Einklang bringen","translation":"to bring into alignment/harmony","pronunciation":"in YN-klang BRING-en","example":"Anforderungen in Einklang bringen."},{"word":"kollidieren mit","translation":"to collide with","pronunciation":"kol-li-DEER-en mit","example":"Mit dem Erhalt kollidieren."},{"word":"fußläufig","translation":"walkable","pronunciation":"FOOS-loy-fikh","example":"Fußläufig erreichbar."},{"word":"decken","translation":"to cover/meet","pronunciation":"DEK-en","example":"Bedarfe decken."},{"word":"der Freiraum","translation":"open space/freedom","pronunciation":"dayr FRY-rowm","example":"Grüne Freiräume."},{"word":"das Leitbild","translation":"guiding concept/vision","pronunciation":"dahs LYT-bild","example":"Stadtplanerisches Leitbild."}]}',
'{"title":"Darauf abzielen, X zu tun — to aim to do X (goal orientation)","pattern":"etwas/jemand zielt darauf ab, X zu tun = something/someone aims to do X (abzielen auf = to aim at — separable; zielt...ab; darauf anticipates the infinitive clause)","explanation":"Darauf abzielen + zu-infinitive = to aim to (do X). Zielen darauf ab, alltägliche Bedarfe zu decken = aims to cover everyday needs. The separable verb abzielen (separable: ab + zielen): zielt...ab. The correlative darauf...zu connects the verb to the infinitive clause. Compare: das Ziel haben/verfolgen, X zu tun (to have the goal of doing X — more nominal), versuchen X zu tun (to try to do X — more effort-oriented), beabsichtigen X zu tun (to intend to do X — more formal deliberate decision), anstreben X zu tun (to strive to do X — more aspirational).","examples":[{"sentence":"Die Kampagne zielt darauf ab, das Bewusstsein zu schärfen.","translation":"The campaign aims to sharpen awareness."},{"sentence":"Die Reform zielt darauf ab, Bürokratie abzubauen.","translation":"The reform aims to reduce bureaucracy."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Fußläufig'' means?","options":["walkable","on foot","pedestrian","accessible"],"correctAnswer":"walkable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Sustainable urban planning must bring contradictory requirements into alignment: densification as a contribution to land protection collides with the preservation of green open spaces and the desire for quality of life in public space.","options":["Nachhaltige Stadtplanung muss widersprüchliche Anforderungen in Einklang bringen: Verdichtung als Beitrag zum Flächenschutz kollidiert mit dem Erhalt grüner Freiflächen und dem Wunsch nach Lebensqualität im öffentlichen Raum.","Stadtplanung muss Wohnen, Natur und öffentlichen Raum balancieren.","Verdichtung und Grünflächen stehen in Stadtplanung im Konflikt.","Nachhaltige Städte müssen mehrere Ziele gleichzeitig verfolgen."],"correctAnswer":"Nachhaltige Stadtplanung muss widersprüchliche Anforderungen in Einklang bringen: Verdichtung als Beitrag zum Flächenschutz kollidiert mit dem Erhalt grüner Freiflächen und dem Wunsch nach Lebensqualität im öffentlichen Raum."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Kampagne zielt darauf ab, das Bewusstsein zu ___.","options":["schärfen","steigern","verbessern","erhöhen"],"correctAnswer":"schärfen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The reform aims to reduce bureaucracy","wordBankItems":["Die","Reform","zielt","darauf","ab",",","Bürokratie","abzubauen","."],"correctAnswer":"Die Reform zielt darauf ab , Bürokratie abzubauen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''In Einklang bringen'' means?","options":["to bring into alignment/harmony","to reconcile","to balance","to coordinate"],"correctAnswer":"to bring into alignment/harmony"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000028c',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss future mobility at B2","Use Mobilität der Zukunft vocabulary","Talk about electric vehicles, public transport, and mobility transition"],"explanation":{"intro":"Future mobility vocabulary covers transport transition, e-mobility, and Germany''s Verkehrswende at B2.","culturalNote":"Mobilität der Zukunft: Germany: Automobilland (car country — VW, BMW, Mercedes, Audi), but facing Verkehrswende (mobility transition). Key: Elektromobilität (e-mobility — charging infrastructure, range anxiety), ÖPNV (öffentlicher Personennahverkehr — public transport — U-Bahn, Straßenbahn, Bus), 49-Euro-Ticket (national public transport ticket 2023 — popular), Deutsche Bahn (state railway — infrastructure issues). Shared Mobility: Carsharing, Bikesharing, Ridesharing. Key debates: Tempolimit (speed limit on Autobahn — Germany one of few without), Dieselfahrverbote (diesel driving bans — German cities). Autonomous vehicles (autonomes Fahren). Klimafolgen des Verkehrs (~20% of German CO2)."},"examples":[{"german":"Die Verkehrswende erfordert nicht nur technologische Innovation — Elektromotoren statt Verbrennern — sondern eine grundlegende Neuorientierung urbaner Infrastruktur, die den Fuß- und Radverkehr sowie öffentliche Verkehrsmittel gegenüber dem Individualverkehr privilegiert.","english":"The mobility transition requires not only technological innovation — electric motors instead of combustion engines — but a fundamental reorientation of urban infrastructure that privileges pedestrian and cycle traffic as well as public transport over individual motorised traffic."},{"german":"Deutschlands Automobilindustrie steht vor einem strukturellen Transformationsdruck: Der globale Paradigmenwechsel zur Elektromobilität erfordert massive Investitionen und bedroht zugleich hunderttausende Arbeitsplätze im Verbrennungsmotorensektor.","english":"Germany''s automotive industry faces structural transformation pressure: the global paradigm shift to electromobility requires massive investments and at the same time threatens hundreds of thousands of jobs in the combustion engine sector."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s mobility transition, automotive industry, and e-mobility at B2."}}',
'{"items":[{"word":"die Neuorientierung","translation":"reorientation","pronunciation":"dee NOY-o-ri-en-TSEER-oong","example":"Grundlegende Neuorientierung."},{"word":"privilegieren","translation":"to privilege","pronunciation":"pri-vi-leh-GEER-en","example":"Radverkehr privilegieren."},{"word":"der Transformationsdruck","translation":"transformation pressure","pronunciation":"dayr trans-for-mah-TSYOHNS-drook","example":"Struktureller Transformationsdruck."},{"word":"bedrohen","translation":"to threaten","pronunciation":"beh-DROH-en","example":"Arbeitsplätze bedrohen."},{"word":"zugleich","translation":"at the same time","pronunciation":"tsoo-GLYKH","example":"Zugleich bedrohen."},{"word":"der Verbrenner","translation":"combustion engine (vehicle)","pronunciation":"dayr fer-BREN-er","example":"Verbrenner vs. Elektromotor."}]}',
'{"title":"Zugleich X und Y — at the same time X and Y (dual effect, often ironic contrast)","pattern":"etwas ist/tut zugleich X und Y = something is/does X and Y at the same time (zugleich = at the same time/simultaneously — marks two simultaneous and often contradictory effects)","explanation":"Zugleich = at the same time, simultaneously. Often used to express ironic or tension-laden simultaneity: two things happening at once that are in tension. Erfordert massive Investitionen und bedroht zugleich Arbeitsplätze = requires massive investments and at the same time threatens jobs (two simultaneous effects — investment needs vs. job losses). Compare: gleichzeitig (simultaneously — more neutral, often more technical), einerseits...andererseits (on the one hand...on the other — more explicit contrast), sowohl...als auch (both...and — symmetric positive), aber gleichzeitig (but simultaneously — slightly weaker irony).","examples":[{"sentence":"Die Maßnahme ist zugleich wirksam und politisch heikel.","translation":"The measure is at the same time effective and politically sensitive."},{"sentence":"Er ist zugleich Täter und Opfer.","translation":"He is at the same time perpetrator and victim."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Privilegieren'' means?","options":["to privilege","to prioritise","to favour","to promote"],"correctAnswer":"to privilege"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The mobility transition requires not only technological innovation — electric motors instead of combustion engines — but a fundamental reorientation of urban infrastructure that privileges pedestrian and cycle traffic as well as public transport over individual motorised traffic.","options":["Die Verkehrswende erfordert nicht nur technologische Innovation — Elektromotoren statt Verbrennern — sondern eine grundlegende Neuorientierung urbaner Infrastruktur, die den Fuß- und Radverkehr sowie öffentliche Verkehrsmittel gegenüber dem Individualverkehr privilegiert.","Die Verkehrswende bedeutet mehr E-Autos und besseren ÖPNV.","Städte müssen für Fahrrad und Fußgänger umgebaut werden, nicht nur für E-Autos.","Nachhaltige Mobilität erfordert mehr als Technologieänderung."],"correctAnswer":"Die Verkehrswende erfordert nicht nur technologische Innovation — Elektromotoren statt Verbrennern — sondern eine grundlegende Neuorientierung urbaner Infrastruktur, die den Fuß- und Radverkehr sowie öffentliche Verkehrsmittel gegenüber dem Individualverkehr privilegiert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Maßnahme ist zugleich wirksam und politisch ___.","options":["heikel","umstritten","schwierig","komplex"],"correctAnswer":"heikel"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He is at the same time perpetrator and victim","wordBankItems":["Er","ist","zugleich","Täter","und","Opfer","."],"correctAnswer":"Er ist zugleich Täter und Opfer ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bedrohen'' means?","options":["to threaten","to endanger","to jeopardise","to put at risk"],"correctAnswer":"to threaten"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000028d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss water supply at B2","Use Wasserversorgung vocabulary","Talk about water scarcity, management, and Germany''s water system"],"explanation":{"intro":"Water supply vocabulary covers water management, scarcity, and Germany''s water infrastructure at B2.","culturalNote":"Wasserversorgung: Germany: relatively water-rich but facing increasing pressure from climate change (drought years 2018-2022 — Niedrigwasser Rhein — low Rhine water levels). Key institutions: Wasserwerke (waterworks), Stadtwerke. Germany: Wasserprivatisierungsdebatte (water privatisation debate — EU directive attempted but pushed back). Trinkwasserqualität (drinking water quality — high). Key global issues: Wasserknappheit (water scarcity — 2 billion people without safe water). Virtuelle Wasserimporte (virtual water — embedded water in traded goods). Grundwasserabsenkung (groundwater decline — agricultural overuse). UN: Water as human right (2010)."},"examples":[{"german":"Wasser ist kein beliebiges Wirtschaftsgut, sondern eine Lebensgrundlage, deren Zugänglichkeit die Vereinten Nationen seit 2010 als Menschenrecht anerkannt haben — eine Einordnung, die Privatisierungsmodellen enge Grenzen setzt.","english":"Water is not just any economic commodity, but a foundation of life, the accessibility of which the United Nations has recognised as a human right since 2010 — a classification that sets narrow limits on privatisation models."},{"german":"Klimabedingte Dürren und veränderte Niederschlagsmuster machen auch wasserreiche Regionen wie Mitteleuropa anfällig für temporäre Wasserknappheit — mit Folgen für Landwirtschaft, Energieerzeugung und Ökosysteme.","english":"Climate-related droughts and changed precipitation patterns make even water-rich regions like Central Europe vulnerable to temporary water scarcity — with consequences for agriculture, energy generation, and ecosystems."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss water as a human right, water scarcity, and Germany''s water system at B2."}}',
'{"items":[{"word":"beliebig","translation":"just any/arbitrary","pronunciation":"beh-LEE-bikh","example":"Kein beliebiges Gut."},{"word":"die Lebensgrundlage","translation":"foundation of life","pronunciation":"dee LAY-bens-groont-lah-geh","example":"Lebensgrundlage Wasser."},{"word":"die Einordnung","translation":"classification/categorisation","pronunciation":"dee YN-ord-noong","example":"Diese Einordnung."},{"word":"enge Grenzen setzen","translation":"to set narrow limits","pronunciation":"ENG-eh GREN-tsen SET-sen","example":"Enge Grenzen setzen."},{"word":"anfällig für","translation":"vulnerable to","pronunciation":"AN-fä-likh für","example":"Anfällig für Knappheit."},{"word":"der Niederschlag","translation":"precipitation","pronunciation":"dayr NEE-der-shlahk","example":"Veränderte Niederschlagsmuster."}]}',
'{"title":"Enge Grenzen setzen + dative — to set narrow limits on something","pattern":"etwas setzt einer Sache enge Grenzen = something sets narrow limits on something (setzen + enge Grenzen + dative — dative marks what is limited; enge/weite Grenzen = narrow/wide limits)","explanation":"Enge Grenzen setzen + dative = to set narrow limits on, to restrict closely. Die Einordnung setzt Privatisierungsmodellen enge Grenzen = The classification sets narrow limits on privatisation models (dative: den Modellen — to the models, limiting them). The phrase communicates that the subject severely restricts the range of what the dative-object can do. Enge (narrow) vs. weite Grenzen (wide limits). Also: klare Grenzen setzen (to set clear limits), Grenzen setzten (to set boundaries — generally). Compare: beschränken auf (to limit to), einschränken (to restrict — more general), einen Riegel vorschieben (to put a stop to — idiomatic/stronger).","examples":[{"sentence":"Das Gesetz setzt der privaten Datenspeicherung enge Grenzen.","translation":"The law sets narrow limits on private data storage."},{"sentence":"Die Verfassung setzt dem Staat in diesem Bereich enge Grenzen.","translation":"The constitution sets narrow limits on the state in this area."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Beliebig'' means?","options":["just any/arbitrary","random","any","optional"],"correctAnswer":"just any/arbitrary"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Water is not just any economic commodity, but a foundation of life, the accessibility of which the United Nations has recognised as a human right since 2010 — a classification that sets narrow limits on privatisation models.","options":["Wasser ist kein beliebiges Wirtschaftsgut, sondern eine Lebensgrundlage, deren Zugänglichkeit die Vereinten Nationen seit 2010 als Menschenrecht anerkannt haben — eine Einordnung, die Privatisierungsmodellen enge Grenzen setzt.","Wasser ist ein Menschenrecht und darf nicht privatisiert werden.","Die UN hat Wasserversorgung als Menschenrecht anerkannt.","Wasser ist zu wichtig, um es dem Markt zu überlassen."],"correctAnswer":"Wasser ist kein beliebiges Wirtschaftsgut, sondern eine Lebensgrundlage, deren Zugänglichkeit die Vereinten Nationen seit 2010 als Menschenrecht anerkannt haben — eine Einordnung, die Privatisierungsmodellen enge Grenzen setzt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Gesetz setzt der privaten Datenspeicherung enge ___.","options":["Grenzen","Regeln","Bedingungen","Vorgaben"],"correctAnswer":"Grenzen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The constitution sets narrow limits on the state in this area","wordBankItems":["Die","Verfassung","setzt","dem","Staat","in","diesem","Bereich","enge","Grenzen","."],"correctAnswer":"Die Verfassung setzt dem Staat in diesem Bereich enge Grenzen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Anfällig für'' means?","options":["vulnerable to","susceptible to","prone to","sensitive to"],"correctAnswer":"vulnerable to"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000028e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss food and agriculture at B2","Use Ernährung und Landwirtschaft vocabulary","Talk about German agriculture, food systems, and sustainability"],"explanation":{"intro":"Food and agriculture vocabulary covers farming systems, food policy, and sustainability of food production at B2.","culturalNote":"Ernährung und Landwirtschaft: Germany: significant agricultural sector (wheat, pork, dairy — Bauernverband — farmers'' lobby). CAP (Gemeinsame Agrarpolitik — Common Agricultural Policy — EU subsidies). Key debates: Agrarwende (agricultural transition — less pesticide, more organic — Ökolandbau), Tierwohl (animal welfare — factory farming criticism), Antibiotikaeinsatz (antibiotic use), Gentechnik (GMO — Germany very sceptical). Bäuerinnen und Bauern (farmers — protest movements 2024 — against subsidy cuts). Ernährungswende (dietary transition — less meat, more plant-based). Germany: strong organic market (Biomarkt), but agricultural structure dominated by large industrial farms."},"examples":[{"german":"Das Ernährungssystem steht vor einem doppelten Druck: Es muss eine wachsende Weltbevölkerung ernähren und gleichzeitig seinen ökologischen Fußabdruck radikal reduzieren — zwei Anforderungen, die in Spannung zueinander stehen, aber nicht unvereinbar sind.","english":"The food system faces a double pressure: it must feed a growing world population and at the same time radically reduce its ecological footprint — two requirements that stand in tension with each other, but are not irreconcilable."},{"german":"Die Agrarsubventionen der EU stehen in der Kritik, weil sie flächenbezogen vergeben werden und damit Großbetriebe überproportional begünstigen, während kleinbäuerliche Strukturen und Agrarökologie strukturell benachteiligt werden.","english":"EU agricultural subsidies are under criticism because they are allocated on the basis of land area and thereby disproportionately benefit large farms, while small-scale farm structures and agroecology are structurally disadvantaged."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s agriculture, EU subsidies, and sustainable food systems at B2."}}',
'{"items":[{"word":"ernähren","translation":"to feed/nourish","pronunciation":"er-NÄH-ren","example":"Weltbevölkerung ernähren."},{"word":"unvereinbar","translation":"irreconcilable","pronunciation":"oon-fer-YN-bahr","example":"Nicht unvereinbar."},{"word":"vergeben","translation":"to allocate/grant","pronunciation":"fer-GAY-ben","example":"Subventionen vergeben."},{"word":"flächenbezogen","translation":"area-based","pronunciation":"FLÄ-khen-beh-tsoh-gen","example":"Flächenbezogen vergeben."},{"word":"überproportional","translation":"disproportionately","pronunciation":"ü-ber-pro-por-tsyo-NAHL","example":"Überproportional begünstigen."},{"word":"die Agrarökologie","translation":"agroecology","pronunciation":"dee ag-RAHR-ö-ko-lo-GEE","example":"Agrarökologie fördern."}]}',
'{"title":"In Spannung zueinander stehen, aber nicht unvereinbar sein — in tension but not irreconcilable","pattern":"X und Y stehen in Spannung zueinander, sind aber nicht unvereinbar = X and Y are in tension with each other, but are not irreconcilable (zueinander = with each other; unvereinbar = irreconcilable)","explanation":"In Spannung zueinander stehen = to stand in tension with each other (zueinander = to each other, with each other — reciprocal). Aber nicht unvereinbar = but not irreconcilable (double negative: not un-reconcilable = can be reconciled). The pattern acknowledges a real tension while asserting that synthesis is possible — avoiding both naive optimism (claiming no tension) and fatalistic pessimism (claiming they can never be reconciled). Common in policy and academic argument: ''X and Y conflict, but we can find a way''.","examples":[{"sentence":"Wirtschaftswachstum und Klimaschutz stehen in Spannung zueinander, schließen sich aber nicht aus.","translation":"Economic growth and climate protection are in tension with each other, but do not exclude each other."},{"sentence":"Freiheit und Sicherheit stehen in Spannung zueinander, sind aber nicht unvereinbar.","translation":"Freedom and security are in tension with each other, but are not irreconcilable."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unvereinbar'' means?","options":["irreconcilable","incompatible","contradictory","mutually exclusive"],"correctAnswer":"irreconcilable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The food system faces a double pressure: it must feed a growing world population and at the same time radically reduce its ecological footprint — two requirements that stand in tension with each other, but are not irreconcilable.","options":["Das Ernährungssystem steht vor einem doppelten Druck: Es muss eine wachsende Weltbevölkerung ernähren und gleichzeitig seinen ökologischen Fußabdruck radikal reduzieren — zwei Anforderungen, die in Spannung zueinander stehen, aber nicht unvereinbar sind.","Das Ernährungssystem muss mehr Menschen ernähren und gleichzeitig nachhaltiger werden.","Ernährung und Umwelt stehen in einem Spannungsverhältnis.","Das globale Nahrungssystem muss nachhaltiger werden, ohne Hunger zu verursachen."],"correctAnswer":"Das Ernährungssystem steht vor einem doppelten Druck: Es muss eine wachsende Weltbevölkerung ernähren und gleichzeitig seinen ökologischen Fußabdruck radikal reduzieren — zwei Anforderungen, die in Spannung zueinander stehen, aber nicht unvereinbar sind."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wirtschaftswachstum und Klimaschutz stehen in Spannung zueinander, schließen sich aber nicht ___.","options":["aus","ab","an","auf"],"correctAnswer":"aus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Freedom and security are in tension with each other but are not irreconcilable","wordBankItems":["Freiheit","und","Sicherheit","stehen","in","Spannung","zueinander",",","sind","aber","nicht","unvereinbar","."],"correctAnswer":"Freiheit und Sicherheit stehen in Spannung zueinander , sind aber nicht unvereinbar ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Überproportional'' means?","options":["disproportionately","excessively","more than proportionate","above the share"],"correctAnswer":"disproportionately"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000028f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss food security at B2","Use Nahrungssicherheit vocabulary","Talk about global hunger, food systems, and agricultural policy"],"explanation":{"intro":"Food security vocabulary covers the four dimensions of food security, global hunger, and policy responses at B2.","culturalNote":"Nahrungssicherheit: FAO (UN Food and Agriculture Organization — Rome). Four dimensions: Verfügbarkeit (availability), Zugänglichkeit (accessibility/affordability), Verwertung (utilisation), Stabilität (stability). Germany: leading food exporter and aid donor. Key issues: Klimawandel und Ernteverluste (climate change and crop losses), Lebensmittelverschwendung (food waste — 12 million tonnes in Germany p.a.), Spekulation mit Nahrungsmitteln (food commodity speculation — price spikes 2008, 2011, 2022), Patente auf Saatgut (seed patents). SDG 2: Zero Hunger. Ukraine war: wheat supply disruption (2022). Key organisations: World Food Programme (WFP — Nobel Peace Prize 2020)."},"examples":[{"german":"Nahrungssicherheit ist kein rein technisches Problem — globale Überproduktion von Kalorien existiert neben massiver Unterversorgung — sondern ein Verteilungs- und Machtproblem, das politische Willensbildung und gerechte Handelsbedingungen erfordert.","english":"Food security is not a purely technical problem — global overproduction of calories exists alongside massive under-supply — but a problem of distribution and power, which requires political will-formation and just trading conditions."},{"german":"Lebensmittelverschwendung ist ein moralisches und ökologisches Paradoxon: Während eine Milliarde Menschen Hunger leiden, werden ein Drittel aller produzierten Lebensmittel nicht gegessen.","english":"Food waste is a moral and ecological paradox: while one billion people suffer from hunger, a third of all food produced is not eaten."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss food security dimensions, global hunger, and food waste at B2."}}',
'{"items":[{"word":"die Überproduktion","translation":"overproduction","pronunciation":"dee ü-ber-pro-dook-TSYOHN","example":"Globale Überproduktion."},{"word":"neben","translation":"alongside/next to (dative)","pronunciation":"NAY-ben","example":"Neben massiver Unterversorgung."},{"word":"die Willensbildung","translation":"will-formation","pronunciation":"dee VIL-ens-bil-doong","example":"Politische Willensbildung."},{"word":"das Paradoxon","translation":"paradox","pronunciation":"dahs pah-rah-DOK-son","example":"Moralisches Paradoxon."},{"word":"leiden","translation":"to suffer","pronunciation":"LY-den","example":"Hunger leiden."},{"word":"die Handelsbedingungen","translation":"trading conditions","pronunciation":"dee HAN-dels-beh-ding-oongen","example":"Gerechte Handelsbedingungen."}]}',
'{"title":"Neben X existiert Y — alongside X, Y exists (co-existence of contrasts)","pattern":"neben X existiert Y = alongside X, Y exists (neben = alongside — spatial but also logical/figurative: two things that co-exist paradoxically or in contrast)","explanation":"Neben X existiert Y = alongside X, Y exists (neben = beside, alongside — preposition + dative). Used to highlight a contrast or paradox: two things that exist simultaneously that seem incompatible. Neben massiver Unterversorgung existiert globale Überproduktion = Alongside massive under-supply, global overproduction exists. The simultaneity is the point — often used for paradox, imbalance, inequality. Compare: während (while — temporal), gleichzeitig (simultaneously — more neutral), einerseits...andererseits (on the one hand...on the other — more explicit), trotz (despite — more concessive).","examples":[{"sentence":"Neben technologischem Fortschritt existieren tiefe strukturelle Ungleichheiten.","translation":"Alongside technological progress, deep structural inequalities exist."},{"sentence":"Neben Reichtum existiert extreme Armut — oft in derselben Stadt.","translation":"Alongside wealth, extreme poverty exists — often in the same city."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Paradoxon'' means?","options":["paradox","contradiction","anomaly","inconsistency"],"correctAnswer":"paradox"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Food security is not a purely technical problem — global overproduction of calories exists alongside massive under-supply — but a problem of distribution and power, which requires political will-formation and just trading conditions.","options":["Nahrungssicherheit ist kein rein technisches Problem — globale Überproduktion von Kalorien existiert neben massiver Unterversorgung — sondern ein Verteilungs- und Machtproblem, das politische Willensbildung und gerechte Handelsbedingungen erfordert.","Hunger ist kein Problem der Produktion, sondern der Verteilung.","Es gibt genug Nahrung auf der Welt — aber sie ist ungleich verteilt.","Hunger entsteht nicht aus Mangel, sondern aus politischem Versagen."],"correctAnswer":"Nahrungssicherheit ist kein rein technisches Problem — globale Überproduktion von Kalorien existiert neben massiver Unterversorgung — sondern ein Verteilungs- und Machtproblem, das politische Willensbildung und gerechte Handelsbedingungen erfordert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Neben technologischem Fortschritt existieren tiefe strukturelle ___.","options":["Ungleichheiten","Probleme","Herausforderungen","Mängel"],"correctAnswer":"Ungleichheiten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Alongside wealth extreme poverty exists often in the same city","wordBankItems":["Neben","Reichtum","existiert","extreme","Armut","—","oft","in","derselben","Stadt","."],"correctAnswer":"Neben Reichtum existiert extreme Armut — oft in derselben Stadt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Willensbildung'' means?","options":["will-formation","decision-making","political will","determination"],"correctAnswer":"will-formation"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000290',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss consumer society at B2","Use Konsumgesellschaft vocabulary","Talk about consumption, consumerism, and alternative lifestyles"],"explanation":{"intro":"Consumer society vocabulary covers consumerism, overconsumption, and debates about sustainable lifestyles at B2.","culturalNote":"Konsumgesellschaft: Germany: strong consumer economy (private consumption ~50% of GDP). Wohlstandsgesellschaft (affluent society). Key critiques: Konsumismus (consumerism — identity through consumption), geplante Obsoleszenz (planned obsolescence — products designed to break), Wegwerfgesellschaft (throwaway society), Fast Fashion. Counter-movements: Minimalismus (minimalism), Repair culture (Reparaturcafés), Sharing economy (Bibliothek der Dinge — things library), Degrowth. Key indicator: Ökologischer Fußabdruck (ecological footprint — Germany well above sustainable level). Suffizienz (sufficiency — intentionally limiting consumption). Werbung (advertising — critical theory: manufacturing desire, Frankfurt School critique)."},"examples":[{"german":"Konsumgesellschaften strukturieren soziale Identität und Status wesentlich über den Erwerb und Besitz von Gütern — eine Logik, die ökologisch nicht nachhaltig ist und von der Konsumkritik als Entfremdung von tieferen menschlichen Bedürfnissen gedeutet wird.","english":"Consumer societies structure social identity and status substantially through the acquisition and possession of goods — a logic that is ecologically not sustainable and is interpreted by consumption criticism as alienation from deeper human needs."},{"german":"Suffizienz als gesellschaftliches Leitbild setzt nicht auf technologischen Fortschritt als alleinige Lösung, sondern auf eine bewusste Entschleunigung von Produktion und Konsum als Voraussetzung für ökologische Zukunftsfähigkeit.","english":"Sufficiency as a societal guiding concept relies not on technological progress as the sole solution, but on a conscious slowing of production and consumption as a prerequisite for ecological future viability."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss consumer society, planned obsolescence, and sufficiency as an alternative at B2."}}',
'{"items":[{"word":"der Erwerb","translation":"acquisition","pronunciation":"dayr er-VERP","example":"Erwerb und Besitz."},{"word":"der Besitz","translation":"possession","pronunciation":"dayr beh-ZITS","example":"Besitz von Gütern."},{"word":"deuten als","translation":"to interpret as","pronunciation":"DOY-ten als","example":"Als Entfremdung deuten."},{"word":"die Entfremdung","translation":"alienation","pronunciation":"dee ent-FREM-doong","example":"Entfremdung von Bedürfnissen."},{"word":"die Entschleunigung","translation":"slowing down","pronunciation":"dee ent-SHLOY-ni-goong","example":"Bewusste Entschleunigung."},{"word":"die Zukunftsfähigkeit","translation":"future viability","pronunciation":"dee TSOO-koonks-fä-ikh-kyt","example":"Ökologische Zukunftsfähigkeit."}]}',
'{"title":"Als X gedeutet werden — to be interpreted as X","pattern":"etwas wird als X gedeutet = something is interpreted as X (deuten als = to interpret as — gedeutet werden = passive; used when the interpretation is a claim or perspective, not an objective fact)","explanation":"Als X gedeutet werden = to be interpreted as X. Passive of deuten als = to interpret as. Von der Konsumkritik als Entfremdung gedeutet = interpreted by consumption criticism as alienation. As X marks the interpretive category assigned (it''s an interpretation, not a neutral description). Gedeutet is the past participle of deuten (to interpret, to point to). Compare: als X bezeichnet werden (to be referred to as X — labelling), als X betrachtet werden (to be regarded as X — evaluative perspective), als X verstanden werden (to be understood as X — comprehension), als X angesehen werden (to be seen as X — social evaluation).","examples":[{"sentence":"Die Krise wird von manchen als Chance gedeutet.","translation":"The crisis is interpreted by some as an opportunity."},{"sentence":"Sein Zögern wurde als Schwäche gedeutet.","translation":"His hesitation was interpreted as weakness."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Entfremdung'' means?","options":["alienation","estrangement","detachment","disconnection"],"correctAnswer":"alienation"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Consumer societies structure social identity and status substantially through the acquisition and possession of goods — a logic that is ecologically not sustainable and is interpreted by consumption criticism as alienation from deeper human needs.","options":["Konsumgesellschaften strukturieren soziale Identität und Status wesentlich über den Erwerb und Besitz von Gütern — eine Logik, die ökologisch nicht nachhaltig ist und von der Konsumkritik als Entfremdung von tieferen menschlichen Bedürfnissen gedeutet wird.","In Konsumgesellschaften definiert man sich über das, was man besitzt.","Konsumkritik interpretiert übermäßigen Konsum als Ausdruck von Entfremdung.","Status durch Konsum zu definieren ist ökologisch und moralisch problematisch."],"correctAnswer":"Konsumgesellschaften strukturieren soziale Identität und Status wesentlich über den Erwerb und Besitz von Gütern — eine Logik, die ökologisch nicht nachhaltig ist und von der Konsumkritik als Entfremdung von tieferen menschlichen Bedürfnissen gedeutet wird."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Krise wird von manchen als Chance ___.","options":["gedeutet","gesehen","betrachtet","angesehen"],"correctAnswer":"gedeutet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: His hesitation was interpreted as weakness","wordBankItems":["Sein","Zögern","wurde","als","Schwäche","gedeutet","."],"correctAnswer":"Sein Zögern wurde als Schwäche gedeutet ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Entschleunigung'' means?","options":["slowing down","deceleration","reduction","restraint"],"correctAnswer":"slowing down"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000291',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the future labour market at B2","Use Arbeitsmarkt der Zukunft vocabulary","Talk about automation, platform work, and new work models"],"explanation":{"intro":"Future labour market vocabulary covers automation, gig economy, and Germany''s New Work debate at B2.","culturalNote":"Arbeitsmarkt der Zukunft: Automatisierung (automation — threat to routine jobs — estimates: 25-35% of German jobs at risk). New Work (concept from Frithjof Bergmann — self-determined, meaningful work). Platform work: Gig economy (Gig-Arbeit — Uber, Deliveroo — precarious). Fachkräftemangel (skilled worker shortage — in IT, health, trades). Vier-Tage-Woche (four-day week — experiments). Homeoffice/Remote work (COVID accelerated — still common). Künstliche Intelligenz und Arbeit (AI and work — displacing cognitive tasks). Bundesagentur für Arbeit (labour market policy). Key tension: Flexibilität (for employers) vs. Sicherheit (for workers). Mitbestimmung (co-determination — Germany''s strong works council tradition)."},"examples":[{"german":"Die Digitalisierung verändert den Arbeitsmarkt nicht gleichförmig: Hochqualifizierte Tätigkeiten mit sozialem Kontakt und kreativer Problemlösung sind weitaus weniger von Automatisierung bedroht als repetitive, routinebasierte Aufgaben — was bestehende Qualifikationsungleichheiten verschärft.","english":"Digitalisation changes the labour market not uniformly: highly qualified activities with social contact and creative problem-solving are far less threatened by automation than repetitive, routine-based tasks — which sharpens existing qualification inequalities."},{"german":"Das Konzept des ''New Work'' hinterfragt die industrielle Arbeitsteilung und setzt auf sinnstiftende, selbstbestimmte Tätigkeiten als Grundlage für Produktivität und Zufriedenheit — eine Vision, die im Spannungsverhältnis zur kapitalistischen Profitlogik steht.","english":"The concept of ''New Work'' questions industrial division of labour and relies on meaningful, self-determined activities as the foundation for productivity and satisfaction — a vision that stands in tension with capitalist profit logic."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss automation, New Work, and Germany''s future labour market at B2."}}',
'{"items":[{"word":"gleichförmig","translation":"uniformly","pronunciation":"GLYKH-für-mikh","example":"Nicht gleichförmig verändert."},{"word":"weitaus","translation":"far/by far","pronunciation":"VYT-ows","example":"Weitaus weniger bedroht."},{"word":"repetitiv","translation":"repetitive","pronunciation":"reh-peh-ti-TEEF","example":"Repetitive Aufgaben."},{"word":"hinterfragen","translation":"to question","pronunciation":"HIN-ter-frah-gen","example":"Arbeitsteilung hinterfragen."},{"word":"sinnstiftend","translation":"meaningful","pronunciation":"ZIN-shtif-tend","example":"Sinnstiftende Tätigkeiten."},{"word":"die Profitlogik","translation":"profit logic","pronunciation":"dee pro-FEET-lo-gik","example":"Kapitalistische Profitlogik."}]}',
'{"title":"Weitaus weniger/mehr X als Y — far less/more X than Y (emphatic comparison)","pattern":"weitaus weniger/mehr X als Y = far less/more X than Y (weitaus = far — emphatic scalar adverb amplifying the comparative; makes the difference large/striking)","explanation":"Weitaus = far (amplifier for comparatives). Weitaus weniger bedroht = far less threatened. Weitaus mehr = far more. Weitaus besser (far better), weitaus schlimmer (far worse), weitaus schwieriger (far more difficult). Compare: viel weniger/mehr (much less/more — less emphatic), erheblich weniger/mehr (considerably less/more — formal), deutlich weniger/mehr (significantly less/more — neutral/common), bei weitem + comparative (by far + comparative — also strong).","examples":[{"sentence":"Das Ergebnis ist weitaus besser als erwartet.","translation":"The result is far better than expected."},{"sentence":"Die Kosten sind weitaus höher als ursprünglich geplant.","translation":"The costs are far higher than originally planned."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Sinnstiftend'' means?","options":["meaningful","purposeful","fulfilling","significant"],"correctAnswer":"meaningful"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Digitalisation changes the labour market not uniformly: highly qualified activities with social contact and creative problem-solving are far less threatened by automation than repetitive, routine-based tasks — which sharpens existing qualification inequalities.","options":["Die Digitalisierung verändert den Arbeitsmarkt nicht gleichförmig: Hochqualifizierte Tätigkeiten mit sozialem Kontakt und kreativer Problemlösung sind weitaus weniger von Automatisierung bedroht als repetitive, routinebasierte Aufgaben — was bestehende Qualifikationsungleichheiten verschärft.","Automatisierung bedroht vor allem einfache, routinierte Tätigkeiten.","Digitalisierung trifft manche Berufe härter als andere.","Kreative und soziale Berufe sind weniger gefährdet als Routineberufe."],"correctAnswer":"Die Digitalisierung verändert den Arbeitsmarkt nicht gleichförmig: Hochqualifizierte Tätigkeiten mit sozialem Kontakt und kreativer Problemlösung sind weitaus weniger von Automatisierung bedroht als repetitive, routinebasierte Aufgaben — was bestehende Qualifikationsungleichheiten verschärft."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Ergebnis ist weitaus besser als ___.","options":["erwartet","geplant","angenommen","vorhergesagt"],"correctAnswer":"erwartet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The costs are far higher than originally planned","wordBankItems":["Die","Kosten","sind","weitaus","höher","als","ursprünglich","geplant","."],"correctAnswer":"Die Kosten sind weitaus höher als ursprünglich geplant ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Hinterfragen'' means?","options":["to question","to challenge","to scrutinise","to critically examine"],"correctAnswer":"to question"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000292',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss basic income at B2","Use Grundeinkommen vocabulary","Talk about UBI debates, pilots, and alternatives"],"explanation":{"intro":"Basic income vocabulary covers universal basic income proposals, pilots, and the debate in Germany at B2.","culturalNote":"Grundeinkommen: Bedingungsloses Grundeinkommen (BGE — unconditional basic income — UBI). Germany: Mein Grundeinkommen (crowdfunded UBI experiments — Michael Bohmeyer). Academic pilot: Pilotprojekt Grundeinkommen (2020-2023, 122 participants, positive mental health results). Key proponents: Götz Werner (dm-Drogeriemarkt founder — financed by VAT reform), Milton Friedman (negative income tax). Key critics: destroys work incentive, expensive. Key alternatives: Bürgergeld (introduced 2023 — replaced Hartz IV — means-tested). Schweizer Volksabstimmung (Swiss referendum 2016 — rejected 77%). Key question: automation → need for basic income?"},"examples":[{"german":"Das bedingungslose Grundeinkommen ist ein Konzept mit politischer Heimatlosigkeit: Libertäre schätzen seine Einfachheit und die Abkehr von paternalistischen Transfersystemen, während Progressivere die Entkopplung von Arbeit und Einkommen als befreiend empfinden — beides aus sehr unterschiedlichen Werten.","english":"Unconditional basic income is a concept with political homelessness: libertarians appreciate its simplicity and the departure from paternalistic transfer systems, while those further left perceive the decoupling of work and income as liberating — both from very different values."},{"german":"Pilotprojekte zum Grundeinkommen zeigen, dass Empfänger es überwiegend für Weiterbildung, Gesundheit und Existenzgründung nutzen — und nicht, wie häufig befürchtet, aufhören zu arbeiten.","english":"Pilot projects on basic income show that recipients predominantly use it for continuing education, health, and starting a business — and do not, as is frequently feared, stop working."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss universal basic income, German experiments, and UBI arguments at B2."}}',
'{"items":[{"word":"die Heimatlosigkeit","translation":"political homelessness","pronunciation":"dee HY-maht-loh-zikh-kyt","example":"Politische Heimatlosigkeit."},{"word":"paternalistisch","translation":"paternalistic","pronunciation":"pah-ter-nah-LIS-tish","example":"Paternalistisch."},{"word":"befreiend","translation":"liberating","pronunciation":"beh-FRY-end","example":"Als befreiend empfinden."},{"word":"der Empfänger","translation":"recipient","pronunciation":"dayr em-PFÄNG-er","example":"Empfänger des Grundeinkommens."},{"word":"die Existenzgründung","translation":"starting a business","pronunciation":"dee eg-zis-TENTS-grün-doong","example":"Existenzgründung."},{"word":"befürchten","translation":"to fear","pronunciation":"beh-FÜR-khten","example":"Wie befürchtet."}]}',
'{"title":"Wie häufig befürchtet — as is frequently feared (established expectation clause)","pattern":"wie häufig befürchtet = as is frequently feared (wie = as — used to introduce a widely-held expectation or worry; befürchtet = past participle of befürchten — feared; this pattern cites the feared outcome before showing it does not happen)","explanation":"Wie häufig/oft befürchtet = as is frequently feared (parenthetical/subordinate modal comparison). Used to name a common fear/expectation, then typically deny it (und nicht, wie häufig befürchtet, aufhören zu arbeiten = and do not, as is frequently feared, stop working). Pattern: [main claim], wie [häufig/oft/allgemein] befürchtet/angenommen/erwartet, [the feared/expected thing does NOT happen]. Related forms: wie erwartet (as expected), wie angenommen (as assumed), wie befürchtet (as feared), wie erhofft (as hoped).","examples":[{"sentence":"Die Reform führte, wie erwartet, zu einer Verbesserung.","translation":"The reform led, as expected, to an improvement."},{"sentence":"Die Preise stiegen nicht, wie befürchtet, ins Unermessliche.","translation":"Prices did not rise, as feared, to immeasurable heights."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Paternalistisch'' means?","options":["paternalistic","patronising","authoritarian","controlling"],"correctAnswer":"paternalistic"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Pilot projects on basic income show that recipients predominantly use it for continuing education, health, and starting a business — and do not, as is frequently feared, stop working.","options":["Pilotprojekte zum Grundeinkommen zeigen, dass Empfänger es überwiegend für Weiterbildung, Gesundheit und Existenzgründung nutzen — und nicht, wie häufig befürchtet, aufhören zu arbeiten.","Grundeinkommensexperimente zeigen, dass die Befürchtungen übertrieben sind.","Empfänger eines Grundeinkommens hören nicht auf zu arbeiten.","UBI-Piloten zeigen positive Auswirkungen auf Bildung und Gesundheit."],"correctAnswer":"Pilotprojekte zum Grundeinkommen zeigen, dass Empfänger es überwiegend für Weiterbildung, Gesundheit und Existenzgründung nutzen — und nicht, wie häufig befürchtet, aufhören zu arbeiten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Preise stiegen nicht, wie befürchtet, ins ___.","options":["Unermessliche","Unendliche","Unberechenbare","Unkontrollierbare"],"correctAnswer":"Unermessliche"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The reform led as expected to an improvement","wordBankItems":["Die","Reform","führte",",","wie","erwartet",",","zu","einer","Verbesserung","."],"correctAnswer":"Die Reform führte , wie erwartet , zu einer Verbesserung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Befürchten'' means?","options":["to fear","to worry","to dread","to be concerned"],"correctAnswer":"to fear"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000293',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the welfare state at B2","Use Wohlfahrtsstaat vocabulary","Talk about Germany''s social model and welfare state debates"],"explanation":{"intro":"Welfare state vocabulary covers Germany''s social insurance system, welfare models, and reform debates at B2.","culturalNote":"Wohlfahrtsstaat: Germany has a Bismarckian welfare state model (continental/conservative type — Esping-Andersen typology). Five social insurance pillars: Rentenversicherung (pension), Krankenversicherung (health), Pflegeversicherung (care), Arbeitslosenversicherung (unemployment), Unfallversicherung (accident). Sozialbudget (~30% of GDP). Key reforms: Hartz IV (2003-2005 — Schröder) → Bürgergeld (2023 — Scholz). Debate: Hängematte (safety net as hammock — moral hazard). Key principle: Äquivalenzprinzip (contributions linked to benefits) vs. Bedarfsprinzip (benefits based on need). EU: European Social Model, posted workers directive. Sozialpartnerschaft (social partnership — unions + employers + state)."},"examples":[{"german":"Der Wohlfahrtsstaat ist der institutionelle Ausdruck einer gesellschaftlichen Solidarität, die jenseits freiwilliger Wohltätigkeit steht: Er garantiert einen sozialen Grundschutz als Bürgerrecht, nicht als Almosen.","english":"The welfare state is the institutional expression of a societal solidarity that stands beyond voluntary charity: it guarantees a basic social protection as a civic right, not as alms."},{"german":"Wohlfahrtsstaaten stehen in permanenter Reformspannung: Sie sollen gesellschaftliche Risiken absichern, ohne Fehlanreize zu setzen, und Bedürftige unterstützen, ohne Eigenverantwortung zu untergraben — ein Balanceakt, der keine statische Lösung kennt.","english":"Welfare states are in permanent reform tension: they should insure against societal risks without creating false incentives, and support those in need without undermining personal responsibility — a balancing act that knows no static solution."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s welfare state, social insurance pillars, and welfare reform debates at B2."}}',
'{"items":[{"word":"jenseits","translation":"beyond","pronunciation":"YEN-zyts","example":"Jenseits freiwilliger Wohltätigkeit."},{"word":"die Wohltätigkeit","translation":"charity","pronunciation":"dee VOHL-tä-tikh-kyt","example":"Freiwillige Wohltätigkeit."},{"word":"das Almosen","translation":"alms","pronunciation":"dahs AL-moh-zen","example":"Nicht als Almosen."},{"word":"absichern","translation":"to insure against/hedge","pronunciation":"AP-zi-khern","example":"Risiken absichern."},{"word":"der Fehlanreiz","translation":"false incentive","pronunciation":"dayr FAY-lan-rits","example":"Fehlanreize setzen."},{"word":"die Eigenverantwortung","translation":"personal responsibility","pronunciation":"dee EYE-gen-fer-ant-vor-toong","example":"Eigenverantwortung."}]}',
'{"title":"Jenseits von X stehen — to stand beyond X (transcending a category)","pattern":"etwas steht jenseits von X = something stands beyond X, transcends X (jenseits = beyond — originally spatial, now also figurative: transcending the limits of something)","explanation":"Jenseits (von) + genitive/von = beyond (jenseits is a preposition: jenseits + genitive or jenseits von + noun). Der Wohlfahrtsstaat steht jenseits freiwilliger Wohltätigkeit = The welfare state stands beyond voluntary charity (it transcends the category of charity — it is structurally different and more). Jenseits von X marks that something exceeds, transcends, or operates in a fundamentally different domain than X. Compare: über X hinaus (beyond X — more directional), über X hinausgehen (to go beyond X — active), außerhalb von X (outside of X — more spatial), mehr als X (more than X — simpler quantitative).","examples":[{"sentence":"Die Frage steht jenseits des unmittelbaren Interesses.","translation":"The question stands beyond immediate interest."},{"sentence":"Diese Entscheidung liegt jenseits meiner Befugnisse.","translation":"This decision lies beyond my authority."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Almosen'' means?","options":["alms","charity","handout","donation"],"correctAnswer":"alms"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The welfare state is the institutional expression of a societal solidarity that stands beyond voluntary charity: it guarantees a basic social protection as a civic right, not as alms.","options":["Der Wohlfahrtsstaat ist der institutionelle Ausdruck einer gesellschaftlichen Solidarität, die jenseits freiwilliger Wohltätigkeit steht: Er garantiert einen sozialen Grundschutz als Bürgerrecht, nicht als Almosen.","Der Wohlfahrtsstaat ist mehr als Charity — er sichert soziale Rechte.","Soziale Sicherheit ist ein Recht, kein Geschenk.","Der Wohlfahrtsstaat schützt alle Bürger durch institutionalisierte Solidarität."],"correctAnswer":"Der Wohlfahrtsstaat ist der institutionelle Ausdruck einer gesellschaftlichen Solidarität, die jenseits freiwilliger Wohltätigkeit steht: Er garantiert einen sozialen Grundschutz als Bürgerrecht, nicht als Almosen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Entscheidung liegt jenseits meiner ___.","options":["Befugnisse","Kompetenzen","Zuständigkeit","Verantwortung"],"correctAnswer":"Befugnisse"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The question stands beyond immediate interest","wordBankItems":["Die","Frage","steht","jenseits","des","unmittelbaren","Interesses","."],"correctAnswer":"Die Frage steht jenseits des unmittelbaren Interesses ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Absichern'' means?","options":["to insure against/hedge","to secure","to protect","to safeguard"],"correctAnswer":"to insure against/hedge"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000294',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss social inequality at B2","Use Soziale Ungleichheit vocabulary","Talk about wealth distribution, Gini coefficient, and inequality trends"],"explanation":{"intro":"Social inequality vocabulary covers wealth distribution, mobility, and inequality measurement at B2.","culturalNote":"Soziale Ungleichheit: Germany: rising inequality since 1990s (Thatcherism effects, reunification, globalisation). Key measure: Gini-Koeffizient (Gini coefficient — 0=perfect equality, 1=one person owns everything — Germany ~0.29 income, ~0.78 wealth). Vermögensungleichheit (wealth inequality — especially high: top 10% own ~67% of wealth). Key concepts: Einkommensungleichheit (income inequality), Chancengleichheit (equality of opportunity), Ergebnisgleichheit (equality of outcome). Key causes: Erbschaft (inheritance), Bildungsungleichheit, Lohnungleichheit. Institut: DIW Berlin (Deutsches Institut für Wirtschaftsforschung). Armutsgefährdungsquote (at-risk-of-poverty rate — ~16% in Germany). EU: Social Scoreboard."},"examples":[{"german":"Soziale Ungleichheit ist nicht zwingend ein Anzeichen des gesellschaftlichen Scheiterns: Moderate Ungleichheit kann Leistungsanreize setzen. Problematisch wird sie, wenn sie Chancengleichheit untergräbt, soziale Kohäsion gefährdet und in politische Ungleichheit umschlägt.","english":"Social inequality is not necessarily a sign of societal failure: moderate inequality can set performance incentives. It becomes problematic when it undermines equality of opportunity, endangers social cohesion, and turns into political inequality."},{"german":"Die Erbschaft ist in Deutschland die wichtigste Quelle der Vermögensakkumulation: Jedes Jahr werden mehrere Hundert Milliarden Euro vererbt, was die Chancenungleichheit zwischen Kindern vermögender und nicht-vermögender Eltern strukturell reproduziert.","english":"Inheritance is in Germany the most important source of wealth accumulation: every year, several hundred billion euros are bequeathed, which structurally reproduces the inequality of opportunity between children of wealthy and non-wealthy parents."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss social inequality, wealth distribution, and Germany''s Gini coefficient at B2."}}',
'{"items":[{"word":"zwingend","translation":"necessarily","pronunciation":"TSVING-end","example":"Nicht zwingend problematisch."},{"word":"das Anzeichen","translation":"sign/indication","pronunciation":"dahs AN-tsy-khen","example":"Anzeichen des Scheiterns."},{"word":"gefährden","translation":"to endanger","pronunciation":"geh-FÄR-den","example":"Kohäsion gefährden."},{"word":"umschlagen in","translation":"to turn into","pronunciation":"OOM-shlah-gen in","example":"In politische Ungleichheit umschlagen."},{"word":"die Erbschaft","translation":"inheritance","pronunciation":"dee ERP-shaft","example":"Erbschaft als Quelle."},{"word":"vererben","translation":"to bequeath","pronunciation":"fer-ER-ben","example":"Vermögen vererben."}]}',
'{"title":"Problematisch werden, wenn... — becoming problematic when... (conditional threshold)","pattern":"etwas wird (erst) problematisch, wenn = something becomes (only) problematic when (wenn-clause sets the threshold condition for the main clause to apply)","explanation":"Problematisch werden, wenn = to become problematic when (wenn = when/if — sets the condition). Moderate Ungleichheit ist nicht problematisch, sie wird es, wenn sie Chancengleichheit untergräbt = Moderate inequality is not problematic; it becomes so when it undermines equality of opportunity. The pattern allows for a nuanced claim: ''X is not inherently bad, but becomes problematic under condition Y.'' The wenn-clause sets the critical threshold. Also: erst dann problematisch, wenn (only problematic when) — even more conditional. Compare: solange nicht (as long as not), wenn...nicht mehr (when no longer), ab dem Punkt, an dem (from the point at which).","examples":[{"sentence":"Konkurrenz ist gesund, wird aber problematisch, wenn sie Kooperation verhindert.","translation":"Competition is healthy, but becomes problematic when it prevents cooperation."},{"sentence":"Kritik ist wertvoll, wird aber problematisch, wenn sie persönlich wird.","translation":"Criticism is valuable, but becomes problematic when it gets personal."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Zwingend'' means?","options":["necessarily","compellingly","inevitably","inherently"],"correctAnswer":"necessarily"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Social inequality is not necessarily a sign of societal failure: moderate inequality can set performance incentives. It becomes problematic when it undermines equality of opportunity, endangers social cohesion, and turns into political inequality.","options":["Soziale Ungleichheit ist nicht zwingend ein Anzeichen des gesellschaftlichen Scheiterns: Moderate Ungleichheit kann Leistungsanreize setzen. Problematisch wird sie, wenn sie Chancengleichheit untergräbt, soziale Kohäsion gefährdet und in politische Ungleichheit umschlägt.","Ungleichheit ist schlecht, wenn sie Chancen einschränkt und Demokratie gefährdet.","Moderate Ungleichheit ist akzeptabel; extreme Ungleichheit ist ein gesellschaftliches Problem.","Ungleichheit hat Vorteile, aber schadet, wenn sie Gerechtigkeit untergräbt."],"correctAnswer":"Soziale Ungleichheit ist nicht zwingend ein Anzeichen des gesellschaftlichen Scheiterns: Moderate Ungleichheit kann Leistungsanreize setzen. Problematisch wird sie, wenn sie Chancengleichheit untergräbt, soziale Kohäsion gefährdet und in politische Ungleichheit umschlägt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Konkurrenz ist gesund, wird aber problematisch, wenn sie Kooperation ___.","options":["verhindert","einschränkt","blockiert","erschwert"],"correctAnswer":"verhindert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Criticism is valuable but becomes problematic when it gets personal","wordBankItems":["Kritik","ist","wertvoll",",","wird","aber","problematisch",",","wenn","sie","persönlich","wird","."],"correctAnswer":"Kritik ist wertvoll , wird aber problematisch , wenn sie persönlich wird ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Gefährden'' means?","options":["to endanger","to threaten","to jeopardise","to put at risk"],"correctAnswer":"to endanger"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

